@charset "UTF-8";
/* -----------------------
リセット
----------------------- */
html, body, h1, h2, h3, h4, ul, ol, dl, li, dt, dd, p, div, span, img, a, table, tr, th, td {
  margin: 0;
  padding: 0;
  border: 0;
  font-weight: normal;
  font-size: 100%;
  vertical-align: baseline;
  -webkit-box-sizing: border-box;
  -moz-box-sizing: border-box;
  box-sizing: border-box;
  list-style: none;
}

article, header, footer, aside, figure, figcaption, nav, section {
  display: block;
  -webkit-box-sizing: border-box;
  -moz-box-sizing: border-box;
  box-sizing: border-box;
}

body {
  line-height: 1;
  -ms-text-size-adjust: 100%;
  -webkit-text-size-adjust: 100%;
}

ol, ul {
  list-style: none;
  list-style-type: none;
}

button {
  background: none;
  border: none;
  outline: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}

a {
  text-decoration: none;
}

img {
  display: block;
}

/* -----------------------
  C_character
----------------------- */
.C_character {
  aspect-ratio: 1/1;
}
.C_character.character-1 {
  background-image: url("../img/character-1.gif");
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
}
@media screen and (min-width: 768px) {
  .C_character.character-1 {
    width: 25vw;
  }
}
@media screen and (max-width: 767px) {
  .C_character.character-1 {
    width: 56.4102564103vw;
  }
}
.C_character.character-2 {
  background-image: url("../img/character-2.webp");
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
}
@media screen and (min-width: 768px) {
  .C_character.character-2 {
    width: 17.1875vw;
  }
}
@media screen and (max-width: 767px) {
  .C_character.character-2 {
    width: 56.4102564103vw;
  }
}

.display__character {
  aspect-ratio: 234/274;
  width: 100%;
  position: relative;
}
.display__character .selected_items-character-character {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}
.display__character .selected_items-item {
  position: absolute;
  object-fit: contain;
  object-position: center;
  z-index: 1;
}

/* -----------------------
  C_categorySide
----------------------- */
.C_categorySide {
  background: #FFF;
  box-shadow: 0px 4px 6px 0px rgba(0, 0, 0, 0.25);
  overflow-y: scroll;
  flex-shrink: 0;
  height: 363px;
  padding: 21px 19px 43px;
}
@media screen and (min-width: 768px) {
  .C_categorySide {
    width: 186px;
  }
}
.C_categorySide--inner .TL {
  color: #7FBF99;
  font-weight: 800;
  font-size: 20px;
}
.C_categorySide--inner ul {
  margin-top: 6px;
}
.C_categorySide--inner ul li {
  border-top: dashed 1px #7FBF99;
  padding: 8px 9px;
  min-height: 30px;
}
.C_categorySide--inner ul li:last-child {
  border-bottom: dashed 1px #7FBF99;
}
.C_categorySide--inner ul li .TX a {
  color: #BFBFBF;
  font-weight: 600;
  line-height: normal;
  font-size: 14px;
}
.C_categorySide--inner ul li .TX.change a {
  color: #4EA772;
}

