}

iframe {
  border: none;
}

/* -----------------------
  anime
----------------------- */
.hover-opa {
  transition: 0.3s;
}
.hover-opa:hover {
  opacity: 0.6;
}

.hover-scale {
  transition: 0.3s;
}
.hover-scale:hover {
  transform: scale(1.1);
}

.up {
  opacity: 0;
}
.up.show {
  opacity: 0;
  transform: translateY(100%);
  animation: up 0.5s ease 0.5s forwards;
}
@keyframes up {
  0% {
    opacity: 0;
    transform: translateY(100%);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.down {
  opacity: 0;
}
.down.show {
  opacity: 0;
  transform: translateY(-100%);
  animation: down 0.5s ease 0.5s forwards;
}
@keyframes down {
  0% {
    opacity: 0;
    transform: translateY(-100%);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.left {
  opacity: 0;
}
.left.show {
  opacity: 0;
  transform: translateX(100%);
  animation: left 0.5s ease 0.5s forwards;
}
@keyframes left {
  0% {
    opacity: 0;
    transform: translateX(100%);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

.right {
  opacity: 0;
}
.right.show {
  opacity: 0;
  transform: translateX(-100%);
  animation: right 0.5s ease 0.5s forwards;
}
@keyframes right {
  0% {
    opacity: 0;
    transform: translateX(-100%);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

.pop {
  opacity: 0;
  transform: scale(0.5);
}
.pop.show {
  opacity: 0;
  transform: scale(0.5);
  animation: pop 0.5s ease 0.5s forwards;
}
@keyframes pop {
  0% {
    opacity: 0;
    transform: scale(0.5);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

