  }
}
.slack-bid .input-area {
  margin-top: 100px;
}
.slack-bid .input-area .label {
  display: block;
  margin: 30px auto 0px;
  width: fit-content;
}
.slack-bid .input-area .label-TL {
  font-size: 16px;
  width: 250px;
  display: inline-block;
}
.slack-bid .input-area .label input {
