  background-color: #ffa36a;
  border-radius: 5px;
  padding: 10px 40px;
  font-size: 18px;
  font-weight: 600;
  color: #FFF;
  cursor: pointer;
  margin: 60px auto 0px;
  display: block;
  transition: all 0.2s ease;
  letter-spacing: 4px;
}
.slack-bid .input-area .wpcf7-submit:hover {
  transition: all 0.2s ease;
  opacity: 0.8;
}
.slack-bid .contents {
