  animation: tree-anime-animal 13s linear infinite;
}
@keyframes tree-anime-animal {
  0% {
    transform: rotate(0deg);
  }
  1% {
    transform: rotate(4deg);
  }
  2% {
    transform: rotate(0deg);
  }
  3% {
    transform: rotate(4deg);
  }
  4% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(0deg);
  }
}

.tree-animal {
  position: absolute;
  top: 30%;
  left: 52%;
  transform: translate(-50%, -50%);
  width: 30%;
  height: 30%;
  animation: tree-animal 13s linear infinite;
  z-index: 10;
